from pathlib import Path
import ast,hashlib,importlib.metadata,json,shutil,urllib.request
from verify_mixed_live import render
frozen=json.loads(Path('rag/eval/baselines/mixed_v1/manifest.json').read_text())
protected=('rag/service/mixed_service.py','rag/service/ticket_service.py','rag/service/intent_classifier.py','rag/service/store_contract.py','rag/service/semantic_router.py','rag/service/routing_prototypes.json','rag/service/answer_service.py','rag/retrieval/search_chunks.py')
for f in protected:assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==frozen['file_sha256'][f],f
old=ast.parse(Path('deploy/backups/langgraph-2026-10-12/retrieval_server.py').read_text());new=ast.parse(Path('rag/service/retrieval_server.py').read_text())
def function(tree,name):return next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==name)
assert ast.dump(function(old,'search_api'))==ast.dump(function(new,'search_api'))
oldtry=next(n for n in function(old,'ask_api').body if isinstance(n,ast.Try))
newtry=next(n for n in function(new,'ask_api').body if isinstance(n,ast.Try))
assert [ast.dump(n) for n in oldtry.body]==[ast.dump(n) for n in newtry.body[1:]]
reports=[]
for filename in ('langgraph_v1_live_run1','langgraph_v1_schema_followup'):
    path=Path('rag/eval/reports')/(filename+'.json');r=json.loads(path.read_text());assert r['run_complete']
    if filename.endswith('schema_followup'):
        r['summary']['unit_tests_passed']=51
        r['schema_compatibility']={'unit_tests_passed':51,'off_switch_original_fields':True,
            'source_sha256':{f:hashlib.sha256(Path(f).read_bytes()).hexdigest() for f in ('rag/service/retrieval_server.py','rag/eval/test_ask_graph.py')}}
        r['runtime_hashes']['rag/service/retrieval_server.py']=r['schema_compatibility']['source_sha256']['rag/service/retrieval_server.py']
    r['summary'].update(extra_smoke_dispatch_checked=len(r['extra_smoke']),total_dispatch_checked=len(r['graph_dispatch']))
    path.write_text(json.dumps(r,ensure_ascii=False,indent=2));reports.append(str(path))
    text=render(r).replace('# 最小混合问题支持：','# LangGraph集成：')
    for row in r['challenge']:
        text=text.replace('## '+row['case']['id']+'\n','## '+row['case']['id']+'\n\n图节点：'+' → '.join(row['response']['node_trace'])+'\n',1)
    for row in r['extra_smoke']:
        text+='\n\n## 额外冒烟：'+row['name']+'\n\n'+row['question']+'\n\n'+row['response']['answer']+'\n\n```json\n'+json.dumps(row['response'],ensure_ascii=False,indent=2)+'\n```\n\n人工评分：待评。'
    path.with_suffix('.md').write_text(text)
base=Path('rag/eval/baselines/langgraph_candidate_v1');base.mkdir(parents=True,exist_ok=False)
files=list(protected)+['rag/service/ask_graph.py','rag/service/graph_tools.py','rag/service/retrieval_server.py','rag/requirements-langgraph.txt','rag/eval/test_ask_graph.py','rag/eval/verify_graph_live.py','docs/LANGGRAPH_MILESTONE_2026-10-12.md','rag/eval/cases/routing_challenge_v1.jsonl']
for f in reports:files.extend([f,str(Path(f).with_suffix('.md'))])
checksums={}
for f in files:
    dest=base/f;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,dest)
    checksums[f]=hashlib.sha256(dest.read_bytes()).hexdigest()
versions={}
for name in ('langgraph','langchain-core','langgraph-checkpoint','langgraph-prebuilt','langgraph-sdk'):
    try:versions[name]=importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:versions[name]=None
manifest={'status':'candidate_not_human_accepted','files':checksums,'dependencies':versions,'unit_tests_passed':51,
    'full_regression_report':reports[0],'latest_schema_and_four_smoke_report':reports[1],
    'protected_mixed_v1_source_unchanged':True,'original_search_handler_unchanged':True,
    'old_ask_body_retained_behind_switch':True,'human_review':'pending_for_all_new_answers',
    'no_secrets_archived':True,'RAG_LANGGRAPH_ENABLED':1,'graph_nodes':['plan','ticket_sql','retrieve_chunks','answer_validate','merge']}
(base/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
print('Verified frozen mixed/SQL/router/prompt/search; old ask body and search handler retained')
print(json.dumps({'candidate':str(base),'files':len(files),'unit_tests':51},ensure_ascii=False))
